UPDATE wizardn.tAthMngr SET MngrName = #{mngrName}, RoleUid = #{roleUid}, CompCode = #{compCode}, DeptCode = #{deptCode}, EmpNo = #{empNo}, LoginId = #{loginId},
Passwd = #{passwd}, Email = #{email}, MobileNo = #{mobileNo}, PhoneNo = #{phoneNo}, ProdApprovYn = #{prodApprovYn},
ShopCode = NULLIF(#{shopCode}, ''), State = #{state}, Remark = #{remark}, ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName} WHERE MngrUid = #{mngrUid}
